"""Deterministic shared-cohort search, using public physiology only.
Run stages with `python /work/output/search.py STAGE`; results checkpointed to JSON.
"""
import json, sys, time, os
import numpy as np
from gri_bench.api import load_instance, Experiment, PARAMETERS, individual_design, glucose_metrics, summarize, save_design
from gri_bench.physiology import fast_trace
OUT='/work/output/'
def design(a,e=180,n=4,t=2,l=0.5124966150526034,L=4):
    return dict(mode='responsive',parameters=dict(zip(PARAMETERS,[a,l,e,n,t,L])))
def evaluate(exp,d,steps=1):
    rows=[]
    for name,seed,variant,p,initial,meals in exp.jobs:
        trace=fast_trace(p,initial,meals,individual_design(d,exp.instance['tdi'][name]),substeps=steps)
        rows.append(dict(patient=name,seed=seed,variant=variant,metrics=glucose_metrics(trace)))
    return dict(**summarize(rows),rows=rows)
def record(stage, records):
    with open(OUT+stage+'.json.tmp','w') as f: json.dump(records,f,indent=2)
    os.replace(OUT+stage+'.json.tmp',OUT+stage+'.json')
def main():
    stage=sys.argv[1] if len(sys.argv)>1 else 'screen'
    ins=load_instance(); exp=Experiment(ins)
    records=[]; start=time.process_time()
    for a in [.00025,.00035,.00045,.00055,.00065,.00075]:
        d=design(a); m=evaluate(exp,d)
        records.append(dict(design=d,metrics=m))
        print(a,{k:v for k,v in m.items() if k!='rows'},flush=True)
    record(stage,records)
    good=[r for r in records if r['metrics']['feasible']]
    if good: save_design(max(good,key=lambda r:r['metrics']['mean_tir'])['design'])
    print('CPU',time.process_time()-start,flush=True)
if __name__=='__main__': main()
